## Setup ----
testthat::skip_if(
  Sys.getenv("RUN_SLOW_TESTS") != "true",
  "Skipping: RUN_SLOW_TESTS is not set to true."
)

# Each test changes a few inputs, runs the model without optimizing, and
# compares the output to a value worked out in R from the inputs, or from
# other model outputs through a closed form. The helpers are in
# helper-integration-tests-properties.R.
data("data_big")
data_4_model <- FIMSFrame(data_big)
default_parameters <- setup_default_parameters(data = data_4_model)
ages <- get_ages(data_4_model)
n_ages <- get_n_ages(data_4_model)
n_years <- get_n_years(data_4_model)
data_years <- seq_len(n_years)
weight_at_age <- weight_at_age_matrix(data_big)

# initialize_fims() creates fleets in the order they first appear in the
# parameters, and the report lists fleet outputs in that order.
fleet_names <- unique(stats::na.omit(default_parameters[["fleet"]]))
fleet_number <- stats::setNames(seq_along(fleet_names), fleet_names)

# The survey selects a different part of the population than the fishery, so
# a mix-up between fleets changes the expected values.
set_survey_inputs <- function(parameters) {
  parameters |>
    dplyr::mutate(
      value = dplyr::case_when(
        label == "log_q" & fleet == "survey1" ~ log(2.5),
        module_name == "Selectivity" & fleet == "survey1" &
          label == "inflection_point" ~ 5,
        module_name == "Selectivity" & fleet == "survey1" &
          label == "slope" ~ 2,
        .default = value
      )
    )
}
parameters <- set_survey_inputs(default_parameters)
report <- run_deterministic(parameters, data_4_model)
# Numbers at age come from the model output. Rows are years and columns are
# ages.
numbers_at_age <- pull_output(report, "numbers_at_age") |>
  matrix(ncol = n_ages, byrow = TRUE)
# The FIMS logistic with slope s is the logistic distribution function with
# scale 1 / s.
survey_selectivity <- stats::plogis(
  ages,
  location = pull_input(
    parameters, "Selectivity", "inflection_point", "survey1"
  ),
  scale = 1 / pull_input(parameters, "Selectivity", "slope", "survey1")
)

## IO correctness ----
test_that("expected survey index is q times selected biomass in each year", {
  catchability <- exp(pull_input(parameters, "Fleet", "log_q", "survey1"))
  # The survey samples numbers at the start of the year. The data_big survey
  # index is in mt, so the expected index is in weight.
  selected_numbers <- sweep(
    numbers_at_age[data_years, ], 2, survey_selectivity, "*"
  )

  #' @description Test that the expected survey index in weight is q times the sum over ages of numbers, selectivity, and weight.
  expect_equal(
    object = pull_output(report, "index_expected", fleet_number[["survey1"]]),
    expected = catchability *
      rowSums(selected_numbers * weight_at_age[data_years, ])
  )
  #' @description Test that the survey index in numbers is q times the sum over ages of numbers and selectivity.
  expect_equal(
    object = pull_output(report, "index_numbers", fleet_number[["survey1"]]),
    expected = catchability * rowSums(selected_numbers)
  )
})

test_that("expected compositions are proportions of expected numbers", {
  # The fishery age composition comes from its catch at age. The survey has no
  # catch data, so its age composition comes from its index at age, where q
  # cancels.
  catch_at_age <- pull_output(
    report, "catch_numbers_at_age", fleet_number[["fleet1"]]
  ) |>
    matrix(ncol = n_ages, byrow = TRUE)
  index_at_age <- sweep(
    numbers_at_age[data_years, ], 2, survey_selectivity, "*"
  )
  expected_age_composition <- list(
    fleet1 = catch_at_age / rowSums(catch_at_age),
    survey1 = index_at_age / rowSums(index_at_age)
  )
  # data_big has 1 age-to-length conversion for every fleet. Each age is
  # rescaled to sum to 1, so a row is the distribution of length at that age.
  age_to_length_conversion <- data_big |>
    dplyr::filter(type == "age_to_length_conversion") |>
    dplyr::arrange(age, length) |>
    dplyr::pull(observed) |>
    matrix(nrow = n_ages, byrow = TRUE)
  age_to_length_conversion <- age_to_length_conversion /
    rowSums(age_to_length_conversion)

  for (fleet_name in fleet_names) {
    #' @description Test that expected age composition proportions for each fleet are its expected numbers at age over their total.
    expect_equal(
      object = pull_output(
        report, "agecomp_proportion", fleet_number[[fleet_name]]
      ),
      expected = as.vector(t(expected_age_composition[[fleet_name]]))
    )
    #' @description Test that expected length composition proportions for each fleet are its age composition times the age-to-length conversion.
    expect_equal(
      object = pull_output(
        report, "lengthcomp_proportion", fleet_number[[fleet_name]]
      ),
      expected = as.vector(t(
        expected_age_composition[[fleet_name]] %*% age_to_length_conversion
      ))
    )
  }
})

test_that("projection years leave the hindcast unchanged", {
  # As in the projections vignette, 1 catch row with -999 in the last
  # projection year extends the model, and FIMSFrame() fills the other data
  # types with -999 for the new years. Weight at age needs a row for each new
  # year and for the year after the last. The -999 rows need an uncertainty
  # because FIMSFrame() fills it with NA.
  n_projection_years <- 2
  projection_years <- n_years + seq_len(n_projection_years)
  projection_frame <- data_big |>
    dplyr::add_row(
      type = "catch",
      fleet = "fleet1",
      timing = n_years + n_projection_years,
      observed = -999,
      unit = "mt"
    ) |>
    dplyr::bind_rows(
      data_big |>
        dplyr::filter(type == "weight_at_age", timing == n_years + 1) |>
        dplyr::slice(rep(seq_len(n_ages), n_projection_years)) |>
        dplyr::mutate(timing = rep(projection_years + 1, each = n_ages))
    ) |>
    FIMSFrame() |>
    get_data() |>
    dplyr::mutate(
      uncertainty = dplyr::case_when(
        type == "catch" & observed == -999 ~
          "~ dlnorm(meanlog = log_catch_expected, sdlog = 0.00999975)",
        type == "index" & observed == -999 ~
          "~ dlnorm(meanlog = log_index_expected, sdlog = 0.19804220)",
        type == "age_comp" & observed == -999 ~
          "~ dmultinom(prob = agecomp_proportion, size = 0)",
        type == "length_comp" & observed == -999 ~
          "~ dmultinom(prob = lengthcomp_proportion, size = 0)",
        .default = uncertainty
      )
    ) |>
    FIMSFrame()
  # The projection F is larger than any hindcast F. The default deviations are
  # 0, so recruitment in the first projection year is the mean recruitment
  # that the hindcast run uses for the year after its last year.
  projection_parameters <- setup_default_parameters(data = projection_frame) |>
    set_survey_inputs() |>
    dplyr::mutate(
      value = dplyr::case_when(
        label == "log_Fmort" & fleet == "fleet1" & timing > n_years ~ log(0.8),
        .default = value
      )
    )
  projection_report <- run_deterministic(
    projection_parameters, projection_frame
  )
  hindcast_years <- seq_len(n_years + 1)
  hindcast_numbers <- seq_len(n_ages * (n_years + 1))

  #' @description Test that the setup adds projection years to the model.
  expect_equal(get_n_years(projection_frame), n_years + n_projection_years)
  #' @description Test that numbers at age through the year after the last hindcast year do not change with projection years.
  expect_equal(
    object = pull_output(projection_report, "numbers_at_age")[hindcast_numbers],
    expected = pull_output(report, "numbers_at_age")
  )
  #' @description Test that spawning biomass through the year after the last hindcast year does not change with projection years.
  expect_equal(
    object = pull_output(projection_report, "spawning_biomass")[hindcast_years],
    expected = pull_output(report, "spawning_biomass")
  )
  #' @description Test that the spawning biomass ratio through the year after the last hindcast year does not change with projection years.
  expect_equal(
    object = pull_output(
      projection_report, "spawning_biomass_ratio"
    )[hindcast_years],
    expected = pull_output(report, "spawning_biomass_ratio")
  )
  for (output_label in c("catch_expected", "index_expected")) {
    for (fleet_name in fleet_names) {
      #' @description Test that expected catch and index for each fleet in hindcast years do not change with projection years.
      expect_equal(
        object = pull_output(
          projection_report, output_label, fleet_number[[fleet_name]]
        )[data_years],
        expected = pull_output(report, output_label, fleet_number[[fleet_name]])
      )
    }
  }
})

